// Real-draw fixture for scripts/verify-gltf-intake.mjs: glTF files in the forms
// the engine now takes in (quantized and Meshopt-compressed geometry, WebP and
// AVIF pictures, punctual lights, cameras and extras on nodes), each drawn
// beside a plain reference of the same content. Every file is generated by the
// script (tests/fixtures/gltf-intake.mjs). Runtime functions come from the
// browser SDK global (Zhuda).
const Z = (globalThis as any).Zhuda;
const Laya = (globalThis as any).Laya;
const out: any = { ready: false, errors: [] as string[] };
(globalThis as any).__INTAKE__ = out;
addEventListener('error', (event) => out.errors.push(String(event.message)));
addEventListener('unhandledrejection', (event) => out.errors.push(String(event.reason)));

const W = 800,
  H = 600;
let context: any;
let gl: WebGLRenderingContext | null = null;
let copy: CanvasRenderingContext2D | null = null;

/** The frame, top row first on both backends. */
function read() {
  if (gl) {
    const raw = new Uint8Array(W * H * 4);
    gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, raw);
    const pixels = new Uint8Array(W * H * 4);
    for (let y = 0; y < H; y++)
      pixels.set(raw.subarray((H - 1 - y) * W * 4, (H - y) * W * 4), y * W * 4);
    return pixels;
  }
  copy!.drawImage(context.canvas, 0, 0, W, H);
  return new Uint8Array(copy!.getImageData(0, 0, W, H).data.buffer);
}
/** Mean and largest per-channel difference, and the share of pixels off by more than 24. */
function compare(a: Uint8Array, b: Uint8Array) {
  let sum = 0,
    max = 0,
    over = 0;
  for (let i = 0; i < a.length; i += 4) {
    const d = Math.max(
      Math.abs(a[i] - b[i]),
      Math.abs(a[i + 1] - b[i + 1]),
      Math.abs(a[i + 2] - b[i + 2]),
    );
    sum +=
      (Math.abs(a[i] - b[i]) + Math.abs(a[i + 1] - b[i + 1]) + Math.abs(a[i + 2] - b[i + 2])) / 3;
    max = Math.max(max, d);
    if (d > 24) over++;
  }
  const n = a.length / 4;
  return { mean: +(sum / n).toFixed(3), max, over: +(over / n).toFixed(5) };
}
/** Share of pixels that are not the clear colour. */
function coverage(p: Uint8Array) {
  let n = 0;
  for (let i = 0; i < p.length; i += 4)
    if (Math.abs(p[i] - p[0]) + Math.abs(p[i + 1] - p[1]) + Math.abs(p[i + 2] - p[2]) > 12) n++;
  return +(n / (p.length / 4)).toFixed(4);
}
const meanLuma = (p: Uint8Array) => {
  let s = 0;
  for (let i = 0; i < p.length; i += 4) s += 0.2126 * p[i] + 0.7152 * p[i + 1] + 0.0722 * p[i + 2];
  return +(s / (p.length / 4)).toFixed(2);
};
const codes = (report: any) =>
  report.diagnostics.map(
    (d: any) => `${d.code}:${d.severity}${d.extension ? ':' + d.extension : ''}`,
  );
const v3 = (a: number[]) => new Laya.Vector3(a[0], a[1], a[2]);

async function main() {
  const renderer = (globalThis as any).ZhudaBundle.renderer === 'webgpu' ? 'webgpu' : 'webgl';
  out.renderer = renderer;
  context = await Z.ZhudaEngine.boot({
    renderer,
    container: document.querySelector('#view'),
    width: W,
    height: H,
    dprCap: 1,
    features: [...(globalThis as any).ZhudaBundle.features],
    preserveDrawingBuffer: true,
  });
  if (renderer === 'webgl')
    gl = context.canvas.getContext('webgl2') || context.canvas.getContext('webgl');
  else {
    const canvas = document.createElement('canvas');
    canvas.width = W;
    canvas.height = H;
    copy = canvas.getContext('2d', { willReadFrequently: true });
  }
  context.runtime.start(() => {});
  const scene = Z.Zhuda3D.createScene3D(context.rootScene, { ambientColor: [0.16, 0.17, 0.2, 1] });
  const camera = Z.Zhuda3D.createCamera(scene, {
    position: [0, 0, 3],
    clearColor: [0.05, 0.06, 0.08, 1],
    fov: 45,
  });
  const ROOM = await (await fetch('./assets/room.json')).json();
  const provider = new Z.DirectoryAssetProvider({ baseUrl: './assets/' });
  const decoders = new Z.ZhudaModelDecoderRegistry();
  decoders.register(new Z.ZhudaMeshoptModelDecoder());
  const library = new Z.ZhudaModelLibrary({ provider, decoders, maxIdle: 0 });

  /** Draws until two frames agree (pipelines and pictures may settle late). */
  const settle = async () => {
    let last: Uint8Array | null = null;
    for (let i = 0; i < 12; i++) {
      Z.ZhudaEngine.flushRenderFrames(2);
      await new Promise((r) => requestAnimationFrame(() => r(null)));
      const now = read();
      if (last && compare(last, now).max === 0) return now;
      last = now;
    }
    return last!;
  };
  const aim = (eye: number[], target: number[], fov: number, near = 0.1, far = 100) => {
    camera.orthographic = false;
    camera.fieldOfView = fov;
    camera.nearPlane = near;
    camera.farPlane = far;
    camera.transform.position = v3(eye);
    camera.transform.lookAt(v3(target), new Laya.Vector3(0, 1, 0));
  };
  // Lights the page makes itself, for the references.
  const handLights: any[] = [];
  const addLight = (type: any, at: number[], setup: (light: any, holder: any) => void) => {
    const holder = new Laya.Sprite3D('HandLight');
    scene.addChild(holder);
    holder.transform.position = v3(at);
    const light = holder.addComponent(type);
    setup(light, holder);
    handLights.push(holder);
  };
  const dropLights = () => {
    for (const holder of handLights.splice(0)) holder.destroy(true);
  };
  let current: any = null;
  const mount = async (id: string, options: any = {}) => {
    current?.dispose();
    current = null;
    current = await library.instantiate(id, options);
    scene.addChild(current.node);
    return current;
  };
  const clear = () => {
    current?.dispose();
    current = null;
    dropLights();
  };

  // The glTF light units, done again here from the documented mapping.
  const encode = (c: number) => (c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055);
  const colorOf = (c: number[]) => new Laya.Color(encode(c[0]), encode(c[1]), encode(c[2]), 1);
  const handRoomLights = () => {
    const lamp = ROOM.lamp.light,
      spot = ROOM.spot.light,
      sun = ROOM.sun.light;
    addLight(Laya.PointLightCom, ROOM.lamp.position, (light) => {
      light.color = colorOf(lamp.color);
      light.range = lamp.range;
      light.intensity = (29 * lamp.intensity * (15 / 16) ** 2) / (Math.PI * lamp.range ** 2);
    });
    addLight(Laya.SpotLightCom, ROOM.spot.position, (light, holder) => {
      const range = 4 * Math.sqrt(spot.intensity / Math.PI);
      light.color = colorOf(spot.color);
      light.range = range;
      light.intensity = (29 * spot.intensity) / (Math.PI * range * range);
      light.spotAngle = (2 * spot.spot.outerConeAngle * 180) / Math.PI;
      holder.transform.lookAt(v3(ROOM.spot.target), new Laya.Vector3(0, 1, 0));
    });
    addLight(Laya.DirectionLightCom, [0, 6, 0], (light, holder) => {
      light.color = colorOf(sun.color);
      light.intensity = sun.intensity / Math.PI;
      const f = ROOM.sun.forward;
      holder.transform.lookAt(v3([f[0], 6 + f[1], f[2]]), new Laya.Vector3(0, 1, 0));
    });
  };
  const roomCamera = () =>
    aim(
      ROOM.camera.position,
      ROOM.camera.target,
      (ROOM.camera.perspective.yfov * 180) / Math.PI,
      ROOM.camera.perspective.znear,
      ROOM.camera.perspective.zfar,
    );
  const gltfCamera = (instance: any) => {
    const shot = instance.gltfNodes.find((n: any) => n.camera);
    Z.applyZhudaGltfCamera(camera, shot.camera, shot.node);
  };
  const keyLight = () =>
    addLight(Laya.DirectionLightCom, [0, 0, 0], (light, holder) => {
      light.color = new Laya.Color(1, 0.97, 0.92, 1);
      light.intensity = 1.1;
      holder.transform.lookAt(v3([-0.5, -1, -0.7]), new Laya.Vector3(0, 1, 0));
    });

  /** The views a picture is taken of; each returns its frame. */
  const views: Record<string, () => Promise<Uint8Array>> = {
    'ring-reference': async () => {
      clear();
      keyLight();
      aim([0, 0.35, 2.6], [0, 0, 0], 42);
      await mount('ring-reference.glb');
      return settle();
    },
    'ring-quantized': async () => {
      clear();
      keyLight();
      aim([0, 0.35, 2.6], [0, 0, 0], 42);
      await mount('ring-quantized.glb');
      return settle();
    },
    'ring-raw': async () => {
      clear();
      keyLight();
      aim([0, 0.35, 2.6], [0, 0, 0], 42);
      await mount('ring-quantized-raw.glb');
      return settle();
    },
    ...Object.fromEntries(
      ['png', 'webp', 'webp-fallback', 'avif'].map((name) => [
        `picture-${name}`,
        async () => {
          clear();
          aim([0, 0, 2.2], [0, 0, 0], 60);
          await mount(`picture-${name}.glb`);
          return settle();
        },
      ]),
    ),
    'room-reference': async () => {
      clear();
      roomCamera();
      await mount('room-plain.glb');
      handRoomLights();
      return settle();
    },
    'room-lights': async () => {
      clear();
      const instance = await mount('room-lights.glb', { lights: true });
      gltfCamera(instance);
      return settle();
    },
    'room-unlit': async () => {
      clear();
      const instance = await mount('room-lights.glb');
      gltfCamera(instance);
      return settle();
    },
    'room-plain-dark': async () => {
      clear();
      roomCamera();
      await mount('room-plain.glb');
      return settle();
    },
    'room-camera-from-file': async () => {
      clear();
      const instance = await mount('room-plain.glb');
      gltfCamera(instance);
      handRoomLights();
      return settle();
    },
  };
  const r: any = {};
  // The device's answer for WebP and AVIF.
  r.imageDecode = await Z.probeZhudaImageDecode();

  // 1. Quantized and Meshopt-compressed geometry against the float reference.
  const ringRef = await views['ring-reference']();
  r.ring = {
    coverage: coverage(ringRef),
    referenceReport: codes(current.compatibility),
  };
  const ringQ = await views['ring-quantized']();
  r.ring.quantizedReport = codes(current.compatibility);
  r.ring.quantizedStatus = current.compatibility.status;
  r.ring.quantized = compare(ringRef, ringQ);
  const ringRaw = await views['ring-raw']();
  r.ring.raw = compare(ringRef, ringRaw);

  // 2. WebP and AVIF pictures against the PNG one.
  const png = await views['picture-png']();
  r.picture = { coverage: coverage(png) };
  for (const name of ['webp', 'webp-fallback', 'avif']) {
    const frame = await views[`picture-${name}`]();
    r.picture[name] = {
      ...compare(png, frame),
      status: current.compatibility.status,
      report: codes(current.compatibility),
    };
  }

  // 3. Punctual lights and the file's camera.
  const reference = await views['room-reference']();
  const lit = await views['room-lights']();
  r.room = {
    lights: compare(reference, lit),
    report: codes(current.compatibility),
    nodes: current.gltfNodes.map((n: any) => ({
      index: n.index,
      name: n.name,
      laya: n.node.name,
      extras: n.extras ?? null,
      camera: n.camera ? { type: n.camera.type, yfovDeg: +n.camera.yfovDeg.toFixed(3) } : null,
      light: n.light ? n.light.type : null,
      component: n.lightComponent
        ? {
            type:
              n.lightComponent instanceof Laya.SpotLightCom
                ? 'spot'
                : n.lightComponent instanceof Laya.PointLightCom
                  ? 'point'
                  : n.lightComponent instanceof Laya.DirectionLightCom
                    ? 'directional'
                    : 'other',
            onNode: n.lightComponent.owner === n.node,
            intensity: +n.lightComponent.intensity.toFixed(5),
            range: n.lightComponent.range === undefined ? null : +n.lightComponent.range.toFixed(4),
          }
        : null,
    })),
  };
  const unlit = await views['room-unlit']();
  r.room.noneAsked = current.gltfNodes.filter((n: any) => n.lightComponent).length;
  const dark = await views['room-plain-dark']();
  r.room.unlitVsPlain = compare(dark, unlit);
  r.room.litVsUnlit = compare(unlit, lit);
  r.room.luma = { reference: meanLuma(reference), lit: meanLuma(lit), unlit: meanLuma(unlit) };
  const fileCamera = await views['room-camera-from-file']();
  r.room.camera = compare(reference, fileCamera);

  // 4. A file a library without a Meshopt decoder must refuse, with its report code.
  const plainLibrary = new Z.ZhudaModelLibrary({ provider, maxIdle: 0 });
  try {
    await plainLibrary.instantiate('ring-quantized.glb');
    r.withoutDecoder = 'accepted';
  } catch (error: any) {
    r.withoutDecoder = {
      name: error.name,
      codes: error.report ? codes(error.report) : null,
    };
  }
  plainLibrary.dispose();

  // 5. Thirty load/unload cycles of the compressed model.
  clear();
  Z.ZhudaEngine.flushRenderFrames(2);
  const before = Z.inspectSceneResources().resources;
  for (let i = 0; i < 30; i++) {
    const instance = await library.instantiate('ring-quantized.glb');
    scene.addChild(instance.node);
    Z.ZhudaEngine.flushRenderFrames(1);
    instance.dispose();
  }
  Z.ZhudaEngine.flushRenderFrames(2);
  r.cycles = {
    before,
    after: Z.inspectSceneResources().resources,
    library: library.report(),
  };

  // 6. The embedded-picture path: LayaAir's own parse against the engine's load.
  // (The script samples the JavaScript heap from outside while each runs.)
  const sampled = async (load: () => Promise<void>) => {
    const t0 = performance.now();
    await load();
    return { ms: +(performance.now() - t0).toFixed(1) };
  };
  let native: any = null,
    engine: any = null;
  out.loadNative = () =>
    sampled(async () => {
      const bytes = await (
        await fetch('./assets/big-picture.glb', { cache: 'no-store' })
      ).arrayBuffer();
      const resource = new Laya.glTFResource();
      await resource._parseglb(bytes, new URL('./assets/big-picture.glb', location.href).href);
      native = { resource, node: resource.create() };
    });
  out.dropNative = () => {
    native.node.destroy(true);
    native.resource.destroy();
    native = null;
  };
  out.loadEngine = () =>
    sampled(async () => {
      engine = await library.instantiate('big-picture.glb');
    });
  out.dropEngine = () => {
    engine.dispose();
    engine = null;
  };
  // Whether the two paths make the same picture.
  out.samePicture = async () => {
    clear();
    aim([0, 0, 2.2], [0, 0, 0], 60);
    await out.loadNative();
    scene.addChild(native.node);
    const a = await settle();
    out.dropNative();
    await mount('big-picture.glb');
    const b = await settle();
    clear();
    return compare(a, b);
  };

  out.show = async (name: string) => {
    await views[name]();
    return name;
  };
  out.intake = r;
  out.backend = {
    selected: context.renderer.selected,
    status: context.renderer.status,
    fallbackAdapter: context.renderer.adapter?.isFallbackAdapter ?? null,
  };
  out.rendererErrors = context.renderer.errors.slice(0, 6);
  out.ready = true;
}
main().catch((error) => {
  out.error = String(error?.stack || error);
});
